sys_script.script:
(function(current, previous) {
    var newState = current.getValue('decision_state');
    var oldState = previous ? previous.getValue('decision_state') : '';

    if (newState == 'approved' && oldState != 'approved') {
        // Compute hash from active selections
        var parts = [];
        var gr = new GlideRecord('x_2316178_contin_0_repl_sel');
        gr.addQuery('continuity_item', current.getUniqueValue());
        gr.addQuery('status', 'active');
        gr.orderBy('replacement_user');
        gr.query();
        while (gr.next()) {
            parts.push(gr.getValue('replacement_user') + '|' + (gr.getValue('planned_hours') || '0'));
        }
        current.setValue('approval_hash', parts.join(';'));
        current.setValue('approved_by', gs.getUserID());
        current.setValue('approved_on', new GlideDateTime().getDisplayValue());
    }
})(current, previous);
